            explodedArgs = append(explodedArgs, rangeStartArgs[idx])
        } else {
            explodedArgs = append(explodedArgs, rangeEndArgs[idx-len(rangeStartArgs)])
        }
    }
    return b.preparedStatement, explodedArgs, nil
}

